// استخراج مصفوفة البيانات من جسم الـ Webhook
const rawData = $input.first().json.body || [];

let combinedText = "📌 *جديد التحديثات من القنوات*\n";
combinedText += "───────────────────\n\n";

let validCount = 0;

rawData.forEach((item) => {
  // يتجاهل الرسائل الفارغة التي لا تحتوي على وصف
  if (item.description && item.description.trim() !== "") {
    validCount++;

    combinedText += `📢 *القناة:* ${item.channel}\n`;
    combinedText += `📝 *الوصف:*\n${item.description.trim()}\n`;

    if (item.link && item.link.trim() !== "") {
      combinedText += `\n🔗 *الرابط:* ${item.link.trim()}\n`;
    }

    combinedText += "\n───────────────────\n\n";
  }
});

// في حال عدم وجود أي محتوى نصي
if (validCount === 0) {
  combinedText = "⚠️ لا توجد تحديثات نصية جديدة في هذه الدورة.";
}

// إرجاع عنصر واحد يحتوي على النص الجاهز للإرسال
return [
  {
    json: {
      text: combinedText.trim()
    }
  }
];
